eEquality';\n30: \n31: const columnsArray = [\n32:   ['eventTime', 'positionFixTime'],\n33:   ['type', 'sharedType'],\n34:   ['address', 'positionAddress'],\n35:   ['attributes', 'commandData'],\n36: ];\n37: const columnsMap = new Map(columnsArray);\n38: \n39: const eventPosition = (item, event) => item.positions.find((p) => p.id === event.positionId);\n40: \n41: const CombinedReportPage = () => {\n42:   const { classes } = useReportStyles();\n43:   const t = useTranslation();\n44: \n45:   const devices = useSelector(\n46:     (state) => state.devices.items,\n47:     deviceEquality(['id', 'name', 'uniqueId']),\n48:   );\n49:   const speedUnit = useAttributePreference('speedUnit');\n50: \n51:   const [columns, setColumns] = usePersistedState('combinedColumns', [\n52:     'eventTime',\n53:     'type',\n54:     'attributes',\n55:   ]);\n56:   const [items, setItems] = useState([]);\n57:   const [loading, setLoading] = useState(false);\n58:   const [selected, setSelected] = useState(null);\n59: \n60:   const itemsCoordinates = useMemo(() => items.flatMap((item) => item.route), [items]);\n61: \n62:   const selectedPosition = selected && eventPosition(selected.item, selected.event);\n63: \n64:   const markers = items.flatMap((item) =>\n65:     item.events\n66:       .map((event) => ({ event, position: eventPosition(item, event) }))\n67:       .filter(({ position }) => position != null)\n68:       .map(({ event, position }) => ({\n69:         latitude: position.latitude,\n70:         longitude: position.longitude,\n71:         image: eventIconKey(event.type),\n72:       })),\n73:   );\n74: \n75:   const onShow = useCatchCallback(async ({ deviceIds, groupIds, from, to }) => {\n76:     const query = new URLSearchParams({ from, to });\n77:     deviceIds.forEach((deviceId) => query.append('deviceId', deviceId));\n78:     groupIds.forEach((groupId) => query.append('groupId', groupId));\n79:     setSelected(null);\n80:     setLoading(true);\n81:     try {\n82:       const respon